package com.nimbusbill.customer.entity; import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="customer_products") public class CustomerProduct{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(optional=false) @JoinColumn(name="customer_id") private Customer customer;@ManyToOne(optional=false) @JoinColumn(name="product_id") private PaymentProduct product;@Column(nullable=false) private boolean enabled;@Column(name="activation_date",nullable=false) private LocalDate activationDate;@Column(name="expiry_date") private LocalDate expiryDate;@Column(name="billing_account_id") private UUID billingAccountId;@Column(name="transaction_limit",precision=19,scale=4) private java.math.BigDecimal transactionLimit;@Column(name="daily_limit",precision=19,scale=4) private java.math.BigDecimal dailyLimit;@Column(name="created_at",nullable=false) private Instant createdAt;@Column(name="updated_at",nullable=false) private Instant updatedAt;@PrePersist void create(){createdAt=Instant.now();updatedAt=createdAt;}@PreUpdate void update(){updatedAt=Instant.now();}public UUID getId(){return id;}public Customer getCustomer(){return customer;}public void setCustomer(Customer v){customer=v;}public PaymentProduct getProduct(){return product;}public void setProduct(PaymentProduct v){product=v;}public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public LocalDate getActivationDate(){return activationDate;}public void setActivationDate(LocalDate v){activationDate=v;}public LocalDate getExpiryDate(){return expiryDate;}public void setExpiryDate(LocalDate v){expiryDate=v;}public UUID getBillingAccountId(){return billingAccountId;}public void setBillingAccountId(UUID v){billingAccountId=v;}public java.math.BigDecimal getTransactionLimit(){return transactionLimit;}public void setTransactionLimit(java.math.BigDecimal v){transactionLimit=v;}public java.math.BigDecimal getDailyLimit(){return dailyLimit;}public void setDailyLimit(java.math.BigDecimal v){dailyLimit=v;}}
